internal sealed class LatticeBRSTLocallyNilpotentExponentialDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Pointwise locally nilpotent Lie exponentials",
        H("Pointwise locally nilpotent Lie exponentials"), Blocks(
            Paragraph(Text("Pointwise locally nilpotent Lie exponentials on an arbitrary complex Lie algebra. The carrier L has a LieRing structure and a compatible LieAlgebra Complex structure; its additive group and complex module are inherited from them. The exact hypothesis is forall x : L, exists N : Nat, (A.toLinearMap^N) x = 0. There is no finite-dimensionality, global nilpotence, uniform exponent or t != 0 premise.")),
            Paragraph(Text("Exact public constructor header:\nnoncomputable def localExpLieEquiv (A : LieDerivation ℂ L L)\n    (hloc : ∀ x : L, ∃ N : ℕ, (A.toLinearMap ^ N) x = 0) (t : ℂ) : L ≃ₗ⁅ℂ⁆ L :=")),
            Paragraph(Text("The inverse function of this actual Lie equivalence is its exponential at -t. Both inverse fields are proved on each bounded kernel using IsNilpotent.exp_neg_mul_exp_self and IsNilpotent.exp_mul_exp_neg_self. Only the three actual public theorems below are registered; private helper counts are not inflated.")),
            Paragraph(Text("Attribution: the completed sealed Pro construction supplies the bounded-kernel route. The original sealed partial source supplies the finite-cutoff starting point. Mathlib LieDerivation theory by Frederic Marbach supplies iterate_apply_lie; Mathlib nilpotent exponential theory by Janos Wolosz supplies uniform exponential identities. This source implements the pointwise gluing and finite bracket convolution. This auxiliary supplier does not complete the original physical Weyl construction or the active Monster -> VOA/CFT/anomaly/fusion/string/AdS goal.")),
            Describe.Lean(DescribeId.Create("latticebrstlocallynilpotentexponential-localExpLieEquiv-apply-of-bound"),
                DeclarationHandle.Create("D5/S3/VertexAlgebra/Lattice/PhysicalLie/LatticeBRSTLocallyNilpotentExponential.localExpLieEquiv_apply_of_bound"),
                H("Finite evaluation at every killing bound"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("SOURCE_ONLY_UNCOMPILED: authored proof; native elaboration, kernel checks and registration acceptance remain pending.")),
                    Paragraph(Text("For A : LieDerivation Complex L L, hloc : forall x, exists N, (A.toLinearMap^N) x = 0, and arbitrary t and x, every killing bound N computes the same finite exponential. The bound is allowed to be zero and t is allowed to be zero.")),
                    Paragraph(Text("Complete literal source preamble and enclosing context:\n/- GID: D5/S3/VertexAlgebra/Lattice/PhysicalLie/LatticeBRSTLocallyNilpotentExponential\n   generality: I\n   mirror-B: D5/B/S3/VertexAlgebra/Lattice/PhysicalLie/LatticeBRSTLocallyNilpotentExponential\n   mirror-E: none(waiver:source-candidate-not-enrolled)\n   anchors: []\n   utility: none\n   digest: pointwise locally nilpotent Lie exponentials on the entire carrier. -/\n\n/-\nSOURCE_ONLY_UNCOMPILED. All proofs below are authored proofs, pending native\nelaboration, kernel and assumption checks. The ambient derivation need only be\npointwise locally nilpotent. No finite-dimensionality or uniform exponent is used.\n\nConstruction: the bounded kernels are modules, with genuinely nilpotent restricted\nendomorphisms. Exponential naturality is used only between bounded kernels.\nBracket preservation is a separate finite Leibniz convolution on the original Lie\nalgebra, with cutoff N + M, including zero bounds. The kernels are not asserted to\nbe Lie subalgebras. This is an auxiliary supplier for the original physical Weyl\nconstruction, not a completion of that construction or the Monster/string goal.\n\nAttribution: the bounded-kernel construction follows the completed, sealed Pro\nmathematical advice supplied with this task. Mathlib's LieDerivation theory\n(Frédéric Marbach) supplies the iterated Leibniz formula; its nilpotent exponential\ntheory supplies uniform naturality and the inverse/parameter identities. The\npassage to pointwise cutoffs and the finite bracket convolution are implemented\nhere. The original partial source supplies the finite-cutoff starting point.\n-/\n\nimport Mathlib.Algebra.Lie.Derivation.Basic\nimport Mathlib.RingTheory.Nilpotent.Exp\nimport Mathlib.Data.Complex.Basic\nimport Mathlib.Tactic\n\nset_option autoImplicit false\nset_option relaxedAutoImplicit false\nset_option backward.isDefEq.respectTransparency false\nset_option maxRecDepth 4096\n\nnoncomputable section\nopen scoped BigOperators\n\nnamespace D5.S3.VertexAlgebra.Lattice.PhysicalLie.LatticeBRSTLocallyNilpotentExponential\n\n/- Restriction of scalars is constructed, not an additional public hypothesis.\n   The instance is local to this file and also supplies the bounded modules. -/\nprivate abbrev complexRatModule (V : Type*) [AddCommGroup V] [Module ℂ V] : Module ℚ V :=\n  Module.compHom V (algebraMap ℚ ℂ)\n\nattribute [local instance] complexRatModule\n\nvariable {L : Type*} [LieRing L] [LieAlgebra ℂ L]\n")),
                    Paragraph(Text("Exact literal theorem header through its outer assignment:\ntheorem localExpLieEquiv_apply_of_bound (A : LieDerivation ℂ L L)\n    (hloc : ∀ x : L, ∃ N : ℕ, (A.toLinearMap ^ N) x = 0)\n    (t : ℂ) (x : L) (N : ℕ) (hx : (A.toLinearMap ^ N) x = 0) :\n    localExpLieEquiv A hloc t x =\n      ∑ n ∈ Finset.range N, ((n.factorial : ℂ)⁻¹ * t ^ n) • (A.toLinearMap ^ n) x := by")),
                    Paragraph(Text("Restrict A.toLinearMap to K_N = ker(A.toLinearMap^N). Its Nth power is zero, including N = 0 on the zero module. Uniform exponential naturality is applied only to inclusions K_N -> K_max(N,M), where both operators are genuinely nilpotent. This proves cutoff independence. A common maximum bound proves additivity; the same bound proves scalar compatibility. The result is a complex-linear map on all L.")),
                    Paragraph(Text("To obtain the Lie equivalence used in this theorem, the iterated Leibniz formula first kills [x,y] at N+M. Expanding its finite exponential gives antidiagonals. The nonzero support is bijected with range N times range M. The identity choose(i+j,i)*i!*j! = (i+j)! gives precisely the product coefficients. Bracket bilinearity completes preservation. Both inverse identities are reused on K_N from Mathlib uniform nilpotent exponentials. No kernel is claimed to be a Lie subalgebra.")),
                    Paragraph(Text("The independent physical Weyl author consumes precisely localExpLieEquiv and this evaluation theorem through the sealed expected-public-interface.txt. The intended derivation is privately -(LieDerivation.inner Complex L L a); no public adjoint wrapper is introduced. No live consumer source or output was read, and no physical theorem is claimed here."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("latticebrstlocallynilpotentexponential-localExpLieEquiv-zero-apply"),
                DeclarationHandle.Create("D5/S3/VertexAlgebra/Lattice/PhysicalLie/LatticeBRSTLocallyNilpotentExponential.localExpLieEquiv_zero_apply"),
                H("Zero parameter"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("SOURCE_ONLY_UNCOMPILED: authored proof; native elaboration, kernel checks and registration acceptance remain pending.")),
                    Paragraph(Text("For the same arbitrary complex Lie algebra and pointwise local-nilpotence hypothesis, the exponential at zero fixes every vector.")),
                    Paragraph(Text("Complete literal source preamble and enclosing context:\n/- GID: D5/S3/VertexAlgebra/Lattice/PhysicalLie/LatticeBRSTLocallyNilpotentExponential\n   generality: I\n   mirror-B: D5/B/S3/VertexAlgebra/Lattice/PhysicalLie/LatticeBRSTLocallyNilpotentExponential\n   mirror-E: none(waiver:source-candidate-not-enrolled)\n   anchors: []\n   utility: none\n   digest: pointwise locally nilpotent Lie exponentials on the entire carrier. -/\n\n/-\nSOURCE_ONLY_UNCOMPILED. All proofs below are authored proofs, pending native\nelaboration, kernel and assumption checks. The ambient derivation need only be\npointwise locally nilpotent. No finite-dimensionality or uniform exponent is used.\n\nConstruction: the bounded kernels are modules, with genuinely nilpotent restricted\nendomorphisms. Exponential naturality is used only between bounded kernels.\nBracket preservation is a separate finite Leibniz convolution on the original Lie\nalgebra, with cutoff N + M, including zero bounds. The kernels are not asserted to\nbe Lie subalgebras. This is an auxiliary supplier for the original physical Weyl\nconstruction, not a completion of that construction or the Monster/string goal.\n\nAttribution: the bounded-kernel construction follows the completed, sealed Pro\nmathematical advice supplied with this task. Mathlib's LieDerivation theory\n(Frédéric Marbach) supplies the iterated Leibniz formula; its nilpotent exponential\ntheory supplies uniform naturality and the inverse/parameter identities. The\npassage to pointwise cutoffs and the finite bracket convolution are implemented\nhere. The original partial source supplies the finite-cutoff starting point.\n-/\n\nimport Mathlib.Algebra.Lie.Derivation.Basic\nimport Mathlib.RingTheory.Nilpotent.Exp\nimport Mathlib.Data.Complex.Basic\nimport Mathlib.Tactic\n\nset_option autoImplicit false\nset_option relaxedAutoImplicit false\nset_option backward.isDefEq.respectTransparency false\nset_option maxRecDepth 4096\n\nnoncomputable section\nopen scoped BigOperators\n\nnamespace D5.S3.VertexAlgebra.Lattice.PhysicalLie.LatticeBRSTLocallyNilpotentExponential\n\n/- Restriction of scalars is constructed, not an additional public hypothesis.\n   The instance is local to this file and also supplies the bounded modules. -/\nprivate abbrev complexRatModule (V : Type*) [AddCommGroup V] [Module ℂ V] : Module ℚ V :=\n  Module.compHom V (algebraMap ℚ ℂ)\n\nattribute [local instance] complexRatModule\n\nvariable {L : Type*} [LieRing L] [LieAlgebra ℂ L]\n")),
                    Paragraph(Text("Exact literal theorem header through its outer assignment:\ntheorem localExpLieEquiv_zero_apply (A : LieDerivation ℂ L L)\n    (hloc : ∀ x : L, ∃ N : ℕ, (A.toLinearMap ^ N) x = 0) (x : L) :\n    localExpLieEquiv A hloc 0 x = x := by")),
                    Paragraph(Text("Choose any killing bound for x and work inside its bounded kernel. The restricted operator multiplied by the zero parameter is zero. IsNilpotent.exp_zero gives the identity endomorphism, and inclusion into L gives x. This includes a zero killing bound.")),
                    Paragraph(Text("This is the identity parameter law for the same global equivalence; it adds no finiteness, positivity or nonzero-parameter assumption.")),
                    Paragraph(Text("This public family law is supplied for downstream exponential calculations; it does not assert a physical Weyl result."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("latticebrstlocallynilpotentexponential-localExpLieEquiv-add-apply"),
                DeclarationHandle.Create("D5/S3/VertexAlgebra/Lattice/PhysicalLie/LatticeBRSTLocallyNilpotentExponential.localExpLieEquiv_add_apply"),
                H("Addition of parameters"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("SOURCE_ONLY_UNCOMPILED: authored proof; native elaboration, kernel checks and registration acceptance remain pending.")),
                    Paragraph(Text("For arbitrary complex s and t and every x in the original carrier, exp((s+t)A)x = exp(sA)(exp(tA)x), under exactly the pointwise local-nilpotence hypothesis.")),
                    Paragraph(Text("Complete literal source preamble and enclosing context:\n/- GID: D5/S3/VertexAlgebra/Lattice/PhysicalLie/LatticeBRSTLocallyNilpotentExponential\n   generality: I\n   mirror-B: D5/B/S3/VertexAlgebra/Lattice/PhysicalLie/LatticeBRSTLocallyNilpotentExponential\n   mirror-E: none(waiver:source-candidate-not-enrolled)\n   anchors: []\n   utility: none\n   digest: pointwise locally nilpotent Lie exponentials on the entire carrier. -/\n\n/-\nSOURCE_ONLY_UNCOMPILED. All proofs below are authored proofs, pending native\nelaboration, kernel and assumption checks. The ambient derivation need only be\npointwise locally nilpotent. No finite-dimensionality or uniform exponent is used.\n\nConstruction: the bounded kernels are modules, with genuinely nilpotent restricted\nendomorphisms. Exponential naturality is used only between bounded kernels.\nBracket preservation is a separate finite Leibniz convolution on the original Lie\nalgebra, with cutoff N + M, including zero bounds. The kernels are not asserted to\nbe Lie subalgebras. This is an auxiliary supplier for the original physical Weyl\nconstruction, not a completion of that construction or the Monster/string goal.\n\nAttribution: the bounded-kernel construction follows the completed, sealed Pro\nmathematical advice supplied with this task. Mathlib's LieDerivation theory\n(Frédéric Marbach) supplies the iterated Leibniz formula; its nilpotent exponential\ntheory supplies uniform naturality and the inverse/parameter identities. The\npassage to pointwise cutoffs and the finite bracket convolution are implemented\nhere. The original partial source supplies the finite-cutoff starting point.\n-/\n\nimport Mathlib.Algebra.Lie.Derivation.Basic\nimport Mathlib.RingTheory.Nilpotent.Exp\nimport Mathlib.Data.Complex.Basic\nimport Mathlib.Tactic\n\nset_option autoImplicit false\nset_option relaxedAutoImplicit false\nset_option backward.isDefEq.respectTransparency false\nset_option maxRecDepth 4096\n\nnoncomputable section\nopen scoped BigOperators\n\nnamespace D5.S3.VertexAlgebra.Lattice.PhysicalLie.LatticeBRSTLocallyNilpotentExponential\n\n/- Restriction of scalars is constructed, not an additional public hypothesis.\n   The instance is local to this file and also supplies the bounded modules. -/\nprivate abbrev complexRatModule (V : Type*) [AddCommGroup V] [Module ℂ V] : Module ℚ V :=\n  Module.compHom V (algebraMap ℚ ℂ)\n\nattribute [local instance] complexRatModule\n\nvariable {L : Type*} [LieRing L] [LieAlgebra ℂ L]\n")),
                    Paragraph(Text("Exact literal theorem header through its outer assignment:\ntheorem localExpLieEquiv_add_apply (A : LieDerivation ℂ L L)\n    (hloc : ∀ x : L, ∃ N : ℕ, (A.toLinearMap ^ N) x = 0) (s t : ℂ) (x : L) :\n    localExpLieEquiv A hloc (s + t) x =\n      localExpLieEquiv A hloc s (localExpLieEquiv A hloc t x) := by")),
                    Paragraph(Text("Choose one killing bound N for x. Both stages preserve K_N because their uniform exponentials are endomorphisms of that module. The scalar multiples s*A_N and t*A_N commute and each has Nth power zero. Mathlib IsNilpotent.exp_add_of_commute gives the identity on K_N; the on-kernel formula transports it back to the original L.")),
                    Paragraph(Text("Only the two bounded operators have a uniform exponent. No global nilpotence is inferred, and the intermediate vector is evaluated in the same bounded module.")),
                    Paragraph(Text("This public family law supports composition in downstream consumers. Kernel-level naturality, cutoffs and convolution helpers receive no public Scribe registrations."))), DescribeRole.Theorem))));
}
